<div id="cyron-support-widget" dir="rtl" data-authenticated="{{ auth()->check() ? '1' : '0' }}">
<button type="button" class="cyron-support-toggle" aria-controls="cyron-support-panel" aria-expanded="false">پشتیبانی</button>
<section id="cyron-support-panel" class="cyron-support-panel" hidden aria-label="پشتیبانی آنلاین">
<header><div><strong>پشتیبانی آنلاین</strong><small>معمولاً در چند دقیقه پاسخ می‌دهیم</small></div><button type="button" class="cyron-support-close" aria-label="بستن">×</button></header>
<div class="cyron-support-messages" aria-live="polite"></div>
<div class="cyron-support-emoji" hidden><button type="button" data-emoji="🙂"><i class="far fa-face-smile"></i></button><button type="button" data-emoji="🙏"><i class="fas fa-hands-praying"></i></button><button type="button" data-emoji="📚"><i class="fas fa-book-open"></i></button><button type="button" data-emoji="✅"><i class="fas fa-circle-check"></i></button><button type="button" data-emoji="❓"><i class="fas fa-circle-question"></i></button><button type="button" data-emoji="❤️"><i class="fas fa-heart"></i></button></div>
<form class="cyron-support-form" enctype="multipart/form-data"><div class="cyron-support-compose"><textarea name="body" rows="2" maxlength="2000" placeholder="پیام خود را بنویسید..." aria-label="متن پیام"></textarea><div class="cyron-support-tools"><label class="cyron-support-file" title="افزودن فایل"><i class="fas fa-paperclip"></i><input name="attachment" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" hidden></label><button type="button" class="cyron-support-emoji-toggle" aria-label="افزودن ایموجی"><i class="far fa-face-smile"></i></button></div></div><button class="cyron-support-send" type="submit" aria-label="ارسال پیام"><i class="fas fa-paper-plane"></i></button></form>
<a class="cyron-support-login" hidden href="{{ route('login') }}">برای شروع گفتگو وارد حساب شوید</a>
</section><div class="cyron-support-toast" role="status" aria-live="polite"></div></div>
<style>
#cyron-support-widget{position:fixed;z-index:1000;bottom:22px;left:22px;font-family:inherit}#cyron-support-widget [hidden]{display:none!important}.cyron-support-toggle{border:0;border-radius:999px;background:#146c94;color:#fff;padding:13px 19px;box-shadow:0 8px 24px #0b3b522e;cursor:pointer;font:inherit}.cyron-support-panel{display:flex;flex-direction:column;width:min(380px,calc(100vw - 28px));height:520px;margin-bottom:10px;background:#fff;border:1px solid #d8e2e8;border-radius:16px;box-shadow:0 18px 50px #1730422e;overflow:hidden}.cyron-support-panel header{display:flex;justify-content:space-between;align-items:center;padding:15px 17px;background:#146c94;color:#fff}.cyron-support-panel header div{display:grid;gap:3px}.cyron-support-panel header small{font-size:11px;opacity:.8}.cyron-support-close{border:0;background:transparent;color:#fff;font-size:25px;cursor:pointer}.cyron-support-messages{flex:1;min-height:0;overflow:auto;padding:15px;background:#f5f8fa}.cyron-support-message{max-width:84%;padding:9px 11px;margin:0 0 10px;border-radius:12px;white-space:pre-wrap;line-height:1.7;font-size:13px}.cyron-support-message.user{margin-right:auto;background:#d9edf5}.cyron-support-message.admin{margin-left:auto;background:#fff;border:1px solid #dce5e9}.cyron-support-message time{display:block;font-size:10px;opacity:.55;margin-top:3px}.cyron-support-message a{display:block;margin-top:6px;color:#146c94}.cyron-support-empty{text-align:center;color:#72838b;font-size:13px}.cyron-support-form{display:flex;align-items:flex-end;gap:8px;padding:13px 13px 16px;background:#fff;border-top:1px solid #edf2f4}.cyron-support-compose{flex:1;border:1px solid #cbd9df;border-radius:12px;overflow:hidden}.cyron-support-form textarea{display:block;width:100%;box-sizing:border-box;resize:none;border:0;outline:0;padding:10px 11px;font:inherit;font-size:12px}.cyron-support-tools{display:flex;gap:8px;padding:3px 8px 7px}.cyron-support-tools button,.cyron-support-file{border:0;background:transparent;color:#146c94;cursor:pointer;font-size:18px}.cyron-support-send{width:40px;height:40px;border:0;border-radius:12px;background:#146c94;color:#fff;cursor:pointer;font-size:19px}.cyron-support-send:disabled{opacity:.55}.cyron-support-emoji{display:flex;gap:7px;padding:8px 13px;background:#f8fafb}.cyron-support-emoji button{border:0;background:transparent;font-size:20px;cursor:pointer}.cyron-support-login{display:block;margin:0 15px 14px;padding:10px;border-radius:10px;background:#edf6f9;color:#146c94;text-align:center;text-decoration:none;font-size:13px}.cyron-support-toast{position:fixed;left:0;bottom:75px;opacity:0;transform:translateY(12px);pointer-events:none;transition:.2s;padding:10px 14px;border-radius:10px;background:#20343d;color:#fff;font-size:12px}.cyron-support-toast.show{opacity:1;transform:translateY(0)}.cyron-support-toast.error{background:#a63d40}@media(max-width:480px){#cyron-support-widget{left:0;bottom:0;width:100%}.cyron-support-toggle{margin:0 14px 14px}.cyron-support-panel{width:100%;height:100dvh;max-height:100dvh;margin:0;border:0;border-radius:0}.cyron-support-form{padding-bottom:max(16px,env(safe-area-inset-bottom))}.cyron-support-toast{left:14px;bottom:82px}}
 </style>
<script>
(function(){const root=document.getElementById('cyron-support-widget');if(!root)return;const panel=root.querySelector('.cyron-support-panel'),toggle=root.querySelector('.cyron-support-toggle'),close=root.querySelector('.cyron-support-close'),messages=root.querySelector('.cyron-support-messages'),form=root.querySelector('.cyron-support-form'),login=root.querySelector('.cyron-support-login'),emoji=root.querySelector('.cyron-support-emoji'),emojiToggle=root.querySelector('.cyron-support-emoji-toggle'),textarea=form.querySelector('textarea'),file=form.querySelector('input[type=file]'),toast=root.querySelector('.cyron-support-toast'),token=document.querySelector('meta[name="csrf-token"]')?.content;let timer,toastTimer;function esc(value){const el=document.createElement('div');el.textContent=value;return el.innerHTML}function notify(text,error){toast.textContent=text;toast.classList.toggle('error',!!error);toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3000)}function showState(html){messages.innerHTML=html}function render(items){showState(items.length?items.map(item=>`<div class="cyron-support-message ${item.sender_type}">${esc(item.body)}${item.attachment?`<a href="${esc(item.attachment.url)}" target="_blank" rel="noopener"><i class="fas fa-paperclip"></i> ${esc(item.attachment.name||'فایل پیوست')}</a>`:''}<time>${esc(item.created_at||'')}</time></div>`).join(''):'<p class="cyron-support-empty">پیام خود را ارسال کنید تا با شما گفتگو کنیم.</p>');messages.scrollTop=messages.scrollHeight}async function load(){if(root.dataset.authenticated!=='1'){showState('<p class="cyron-support-empty">برای گفتگو، ابتدا وارد حساب کاربری شوید.</p>');form.hidden=true;login.hidden=false;return}form.hidden=false;login.hidden=true;showState('<p class="cyron-support-empty">در حال بارگذاری گفتگو...</p>');try{const response=await fetch('/support/messages',{headers:{Accept:'application/json'},credentials:'same-origin'});let payload=null;try{payload=await response.json()}catch(e){}if(!response.ok){showState(`<p class="cyron-support-empty">${response.status===401?'نشست شما منقضی شده است. دوباره وارد شوید.':'بارگذاری گفتگو ناموفق بود.'}</p>`);if(response.status===401){form.hidden=true;login.hidden=false}return}if(payload&&payload.success){render(payload.data.messages)}else showState('<p class="cyron-support-empty">گفتگویی پیدا نشد. پیام خود را ارسال کنید.</p>')}catch(e){showState('<p class="cyron-support-empty">اتصال به پشتیبانی برقرار نشد.</p>');notify('اتصال به پشتیبانی برقرار نشد.',true)}}function stop(){if(timer){clearInterval(timer);timer=null}}toggle.addEventListener('click',()=>{const open=panel.hidden;panel.hidden=!open;toggle.setAttribute('aria-expanded',String(open));if(open){load();stop();timer=setInterval(load,10000)}else stop()});close.addEventListener('click',()=>{panel.hidden=true;toggle.setAttribute('aria-expanded','false');stop()});emojiToggle.addEventListener('click',()=>emoji.hidden=!emoji.hidden);emoji.querySelectorAll('button').forEach(button=>button.addEventListener('click',()=>{textarea.value+=button.dataset.emoji;textarea.focus()}));file.addEventListener('change',()=>{if(file.files[0])notify('فایل انتخاب شد: '+file.files[0].name)});form.addEventListener('submit',async event=>{event.preventDefault();const body=textarea.value.trim();if(!body&&!file.files.length){notify('متن یا فایل پیام را وارد کنید.',true);return}const button=form.querySelector('.cyron-support-send');button.disabled=true;try{const response=await fetch('/support/messages',{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':token||''},credentials:'same-origin',body:new FormData(form)});const payload=await response.json();if(response.ok&&payload.success){form.reset();emoji.hidden=true;notify('پیام ارسال شد.');await load()}else notify(payload.message||'ارسال پیام ناموفق بود.',true)}catch(e){notify('خطا در اتصال به پشتیبانی.',true)}finally{button.disabled=false}})})();
 </script>
